function wordsInsideOthers(words: string[]): string[] {
  const out: string[] = [];
  for (let i = 0; i < words.length; i++) {
    for (let j = 0; j < words.length; j++) {
      if (i !== j && words[j].includes(words[i])) {
        out.push(words[i]);
        break;
      }
    }
  }
  return out;
}

